import React, { useState, useEffect } from 'react';
import { 
  Settings, 
  Bell, 
  Clock, 
  RefreshCw, 
  Save, 
  CheckCircle,
  AlertTriangle
} from 'lucide-react';

const SettingsPage = () => {
  const [settings, setSettings] = useState({
    updateTime: '08:00',
    autoRefresh: true,
    refreshInterval: 30,
    notifications: true,
    preferredCategories: [],
    theme: 'light',
    language: 'zh'
  });

  const [saveStatus, setSaveStatus] = useState(null);

  const categories = [
    'AI新闻', 'AI框架', '新算法', '新思路', '新工具'
  ];

  useEffect(() => {
    // 从本地存储加载设置
    const savedSettings = localStorage.getItem('ainews-settings');
    if (savedSettings) {
      setSettings(JSON.parse(savedSettings));
    }
  }, []);

  const handleSettingChange = (key, value) => {
    setSettings(prev => ({
      ...prev,
      [key]: value
    }));
  };

  const handleCategoryToggle = (category) => {
    setSettings(prev => ({
      ...prev,
      preferredCategories: prev.preferredCategories.includes(category)
        ? prev.preferredCategories.filter(c => c !== category)
        : [...prev.preferredCategories, category]
    }));
  };

  const saveSettings = () => {
    try {
      localStorage.setItem('ainews-settings', JSON.stringify(settings));
      setSaveStatus('success');
      setTimeout(() => setSaveStatus(null), 3000);
    } catch (error) {
      console.error('保存设置失败:', error);
      setSaveStatus('error');
      setTimeout(() => setSaveStatus(null), 3000);
    }
  };

  const manualRefresh = async () => {
    try {
      const response = await fetch('/api/news/update', { method: 'POST' });
      const data = await response.json();

      if (data.success) {
        setSaveStatus('refresh-success');
        setTimeout(() => setSaveStatus(null), 3000);
      } else {
        throw new Error(data.error);
      }
    } catch (error) {
      console.error('手动刷新失败:', error);
      setSaveStatus('refresh-error');
      setTimeout(() => setSaveStatus(null), 3000);
    }
  };

  return (
    <div className="max-w-4xl mx-auto">
      {/* 页面标题 */}
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900 flex items-center">
          <Settings className="w-8 h-8 mr-3" />
          系统设置
        </h1>
        <p className="text-gray-600 mt-2">配置AI资讯平台的行为和偏好</p>
      </div>

      {/* 保存状态提示 */}
      {saveStatus && (
        <div className={`mb-6 p-4 rounded-lg flex items-center ${
          saveStatus === 'success' ? 'bg-green-50 text-green-700' :
          saveStatus === 'error' ? 'bg-red-50 text-red-700' :
          saveStatus === 'refresh-success' ? 'bg-blue-50 text-blue-700' :
          'bg-orange-50 text-orange-700'
        }`}>
          {saveStatus === 'success' && <CheckCircle className="w-5 h-5 mr-2" />}
          {saveStatus === 'error' && <AlertTriangle className="w-5 h-5 mr-2" />}
          {saveStatus === 'refresh-success' && <RefreshCw className="w-5 h-5 mr-2" />}
          {saveStatus === 'refresh-error' && <AlertTriangle className="w-5 h-5 mr-2" />}
          {saveStatus === 'success' && '设置已保存成功'}
          {saveStatus === 'error' && '保存设置失败，请重试'}
          {saveStatus === 'refresh-success' && '手动刷新完成'}
          {saveStatus === 'refresh-error' && '手动刷新失败，请检查网络'}
        </div>
      )}

      <div className="space-y-8">
        {/* 自动更新设置 */}
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
          <h2 className="text-xl font-semibold text-gray-900 mb-4 flex items-center">
            <Clock className="w-5 h-5 mr-2" />
            自动更新设置
          </h2>

          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <div>
                <label className="text-sm font-medium text-gray-700">自动更新</label>
                <p className="text-sm text-gray-500">启用每日自动获取最新AI资讯</p>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input
                  type="checkbox"
                  checked={settings.autoRefresh}
                  onChange={(e) => handleSettingChange('autoRefresh', e.target.checked)}
                  className="sr-only peer"
                />
                <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-blue-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
              </label>
            </div>

            <div className="flex items-center justify-between">
              <div>
                <label className="text-sm font-medium text-gray-700">更新时间</label>
                <p className="text-sm text-gray-500">每日自动更新的时间</p>
              </div>
              <input
                type="time"
                value={settings.updateTime}
                onChange={(e) => handleSettingChange('updateTime', e.target.value)}
                className="px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                disabled={!settings.autoRefresh}
              />
            </div>

            <div className="flex items-center justify-between">
              <div>
                <label className="text-sm font-medium text-gray-700">刷新间隔</label>
                <p className="text-sm text-gray-500">页面自动刷新的间隔（分钟）</p>
              </div>
              <select
                value={settings.refreshInterval}
                onChange={(e) => handleSettingChange('refreshInterval', parseInt(e.target.value))}
                className="px-3 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-transparent"
              >
                <option value={0}>不自动刷新</option>
                <option value={15}>15分钟</option>
                <option value={30}>30分钟</option>
                <option value={60}>1小时</option>
                <option value={180}>3小时</option>
              </select>
            </div>

            {/* 手动刷新按钮 */}
            <div className="pt-4 border-t border-gray-200">
              <button
                onClick={manualRefresh}
                className="inline-flex items-center px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
              >
                <RefreshCw className="w-4 h-4 mr-2" />
                立即刷新新闻
              </button>
            </div>
          </div>
        </div>

        {/* 通知设置 */}
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
          <h2 className="text-xl font-semibold text-gray-900 mb-4 flex items-center">
            <Bell className="w-5 h-5 mr-2" />
            通知设置
          </h2>

          <div className="space-y-4">
            <div className="flex items-center justify-between">
              <div>
                <label className="text-sm font-medium text-gray-700">启用通知</label>
                <p className="text-sm text-gray-500">接收重要AI资讯的推送通知</p>
              </div>
              <label className="relative inline-flex items-center cursor-pointer">
                <input
                  type="checkbox"
                  checked={settings.notifications}
                  onChange={(e) => handleSettingChange('notifications', e.target.checked)}
                  className="sr-only peer"
                />
                <div className="w-11 h-6 bg-gray-200 peer-focus:outline-none peer-focus:ring-4 peer-focus:ring-blue-300 rounded-full peer peer-checked:after:translate-x-full peer-checked:after:border-white after:content-[''] after:absolute after:top-[2px] after:left-[2px] after:bg-white after:border-gray-300 after:border after:rounded-full after:h-5 after:w-5 after:transition-all peer-checked:bg-blue-600"></div>
              </label>
            </div>
          </div>
        </div>

        {/* 偏好设置 */}
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
          <h2 className="text-xl font-semibold text-gray-900 mb-4">内容偏好</h2>

          <div className="space-y-4">
            <div>
              <label className="text-sm font-medium text-gray-700 mb-2 block">
                关注的资讯分类
              </label>
              <p className="text-sm text-gray-500 mb-3">选择您感兴趣的AI资讯分类</p>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                {categories.map((category) => (
                  <label key={category} className="flex items-center">
                    <input
                      type="checkbox"
                      checked={settings.preferredCategories.includes(category)}
                      onChange={() => handleCategoryToggle(category)}
                      className="rounded border-gray-300 text-blue-600 focus:ring-blue-500"
                    />
                    <span className="ml-2 text-sm text-gray-700">{category}</span>
                  </label>
                ))}
              </div>
            </div>
          </div>
        </div>

        {/* 系统信息 */}
        <div className="bg-white rounded-lg shadow-sm border border-gray-200 p-6">
          <h2 className="text-xl font-semibold text-gray-900 mb-4">系统信息</h2>

          <div className="space-y-3 text-sm">
            <div className="flex justify-between">
              <span className="text-gray-500">版本:</span>
              <span className="text-gray-900">v1.0.0</span>
            </div>
            <div className="flex justify-between">
              <span className="text-gray-500">最后更新:</span>
              <span className="text-gray-900">
                {localStorage.getItem('ainews-last-update') || '未记录'}
              </span>
            </div>
            <div className="flex justify-between">
              <span className="text-gray-500">运行状态:</span>
              <span className="text-green-600">正常</span>
            </div>
          </div>
        </div>

        {/* 保存按钮 */}
        <div className="flex justify-end space-x-4">
          <button
            onClick={() => {
              localStorage.removeItem('ainews-settings');
              setSettings({
                updateTime: '08:00',
                autoRefresh: true,
                refreshInterval: 30,
                notifications: true,
                preferredCategories: [],
                theme: 'light',
                language: 'zh'
              });
              setSaveStatus('reset-success');
              setTimeout(() => setSaveStatus(null), 3000);
            }}
            className="px-6 py-2 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors"
          >
            重置设置
          </button>

          <button
            onClick={saveSettings}
            className="inline-flex items-center px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors"
          >
            <Save className="w-4 h-4 mr-2" />
            保存设置
          </button>
        </div>
      </div>
    </div>
  );
};

export default SettingsPage;
